INSERT INTO TB_NOTIFICATION (
recipient_user_id,
sender_user_id,
notification_type,
target_type,
target_id
)
SELECT
recipient.user_id,
#{senderUserId},
#{notificationType},
#{targetType},
#{targetId}
FROM TB_USER recipient
WHERE recipient.user_id = #{recipientUserId}
AND recipient.notify_like = 1
AND recipient.user_id != #{senderUserId}
AND NOT EXISTS (
SELECT 1
FROM TB_NOTIFICATION existing
WHERE existing.recipient_user_id = recipient.user_id
AND existing.sender_user_id = #{senderUserId}
AND existing.notification_type = #{notificationType}
AND existing.target_type = #{targetType}
AND existing.target_id = #{targetId}
)
